datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Task {
  id          Int     @id @default(autoincrement())
  description String
  isDone      Boolean @default(false)
}

model EventLog {
  id        Int      @id @default(autoincrement())
  message   String
  createdAt DateTime @default(now())
}

import { startupJob } from "wasp/server/jobs"

export const setup = async () => {
  console.log("Server setup: submitting startup job...")
  await startupJob.submit()
}

export const runStartupJob = async (args, context) => {
  console.log("Startup job running...")
  await context.entities.EventLog.create({
    data: {
      message: "Startup job executed"
    }
  })
  console.log("Startup job completed successfully.")
}

app taskvault {
  wasp: {
    version: "^0.16.0"
  },
  title: "TaskVault",
  server: {
    setupFn: import { setup } from "@src/serverSetup"
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

query getTasks {
  fn: import { getTasks } from "@src/queries",
  entities: [Task]
}

action createTask {
  fn: import { createTask } from "@src/actions",
  entities: [Task]
}

api getStats {
  fn: import { getStats } from "@src/apis",
  httpRoute: (GET, "/api/stats"),
  entities: [Task]
}

job startupJob {
  executor: PgBoss,
  perform: {
    fn: import { runStartupJob } from "@src/jobs/startupJob"
  },
  entities: [EventLog]
}
